export const connect = async ({ port, root, timeout = 30000 }) => {
  const deadline = Date.now() + timeout;
  for (;;) {
    const client = await findVaultTarget({ port, root }).catch(() => null);
    if (client) {
      await client.activate();
      return client;
    }
    if (Date.now() > deadline) throw new Error(`No CDP page target for vault ${root} on :${port}`);
    await new Promise((r) => setTimeout(r, 250));
  }
};

const open = async (url) => {
  const WebSocket = await resolveWebSocket();
  const ws = new WebSocket(url);
  let id = 0;
  const pending = new Map();

  await new Promise((resolve, reject) => {
    ws.addEventListener("open", resolve, { once: true });
    ws.addEventListener("error", (e) => reject(e.error ?? new Error("websocket error")), {
      once: true,
    });
  });
  ws.addEventListener("message", (event) => {
    const msg = JSON.parse(event.data.toString());
    const entry = msg.id && pending.get(msg.id);
    if (!entry) return;
    pending.delete(msg.id);
    if (msg.error) entry.reject(new Error(json(msg.error)));
    else entry.resolve(msg.result);
  });

  const send = (method, params = {}) =>
    new Promise((resolve, reject) => {
      const nextId = ++id;
      pending.set(nextId, { resolve, reject });
      ws.send(json({ id: nextId, method, params }));
    });

  // Body runs inside a plain function: no top-level await, return a promise chain instead.
  const evaluate = async (expression) => {
    const body = /\breturn\b/.test(expression) ? expression : `return (${expression});`;
    const result = await send("Runtime.evaluate", {
      expression: `(() => { ${body} })()`,
      awaitPromise: true,
      returnByValue: true,
    });
    if (result.exceptionDetails) {
      const d = result.exceptionDetails;
      throw new Error(`evaluate failed: ${d.exception?.description ?? d.text}\n${expression}`);
    }
    return result.result.value;
  };

  const waitFor = async (expression, { timeout = 5000, label } = {}) => {
    const deadline = Date.now() + timeout;
    for (;;) {
      if ((await evaluate(expression).catch(() => false)) === true) return;
      if (Date.now() > deadline) throw new Error(`timeout waiting for ${label ?? expression}`);
      await new Promise((r) => setTimeout(r, POLL_MS));
    }
  };

  // `type` after the spread: a caller's `type` would otherwise send two keydowns.
  const key = async (opts = {}) => {
    for (const type of ["keyDown", "keyUp"]) await send("Input.dispatchKeyEvent", { ...opts, type });
  };

  const typeText = async (text) => {
    for (const char of text) await key({ text: char, key: char });
  };

  const pressEscape = () =>
    key({ key: "Escape", code: "Escape", windowsVirtualKeyCode: 27, nativeVirtualKeyCode: 27 });

  // Keeps the renderer unthrottled and focused even when Obsidian is not frontmost.
