      await proof.obsidian.closeModals();
      if (app.workspace.getActiveFile() && app.workspace.getActiveFile().path === window.pk2228.canvasPath) { editor().selectNone(); editor().setCurrentTool('select'); return true; }
      return window.pk2228.openCanvas();
    },
  };
  return true;
})()"""

FRESH_CANVAS = r"""(async () => {
  for (const leaf of app.workspace.getLeavesOfType('tldraw-dg-preview')) leaf.detach();
  app.workspace.leftSplit.collapse();
  app.workspace.rightSplit.collapse();
