  app.commands.executeCommandById(command.id);
  await proof.waitFor(() => app.workspace.activeLeaf.view.getViewType() === 'tldraw-dg-preview' && pk2228.editor(), { what: 'a new canvas', timeout: 15000 });
  pk2228.canvasPath = app.workspace.getActiveFile().path;
  return true;
})()"""

