// Turns a model's case proposal into kit cases a person decides on. The model only
// proposes; every rule that can be checked without it is checked here.
import { validateKit, type Kit, type SurfaceArea, type TestCase } from "../src/core/kit";

export type DoneWhen = { number: number; text: string };

export type ProposedArea = {
  key: string;
  area: string;
  why: string;
  files: string[];
  probability: number;
  impact: number;
};

export type ProposedCase = {
  kind: "acceptance" | "regression";
  doneWhen?: DoneWhen;
  areaKey?: string;
  title: string;
  given: string;
  intent: string;
  then: string;
  variants?: string[];
  priority: "P0" | "P1" | "P2" | "P3";
  protects: string;
  failsWhen: string;
  whyNew: string;
};

export type Proposal = {
  areas: ProposedArea[];
  cases: ProposedCase[];
  extend: Array<{ caseId: string; add: string }>;
  notE2E: Array<{ doneWhen: number; reason: string }>;
  questions: Array<{ about: string; question: string }>;
  assumptions: string[];
};

// What merge dropped and why, so the person sees the model's misses too.
export type Dropped = { what: string; reason: string };

// Regression cases need probability × impact of at least this.
export const MIN_RISK = 3;
const PRIORITIES = ["P0", "P1", "P2", "P3"];

// The "## Done When" section's bullets, numbered in order. Nested bullets stay with their parent.
export const parseDoneWhen = (ticket: string): DoneWhen[] => {
  const lines = ticket.split("\n");
  const start = lines.findIndex((line) => /^#{1,4}\s*done when\b/i.test(line.trim()));
  if (start < 0) return [];
  const bullets: DoneWhen[] = [];
  for (const line of lines.slice(start + 1)) {
    if (/^#{1,4}\s/.test(line.trim())) break;
    const top = /^[*-]\s+(.*)$/.exec(line);
    if (top) bullets.push({ number: bullets.length + 1, text: top[1].trim() });
    else if (/^\s+[*-]\s+/.test(line) && bullets.length) bullets[bullets.length - 1].text += `; ${line.trim().replace(/^[*-]\s+/, "")}`;
  }
  return bullets;
};

const isText = (value: unknown): value is string => typeof value === "string" && value.trim().length > 0;
const plain = (text: string): string => text.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();

export const slug = (text: string, max = 48): string =>
  plain(text).replace(/\s+/g, "-").slice(0, max).replace(/-+$/, "") || "case";

// Accepts the model's JSON, possibly inside a ```json fence, and checks its shape.
export const parseProposal = (raw: string): Proposal => {
  const fenced = /```(?:json)?\s*([\s\S]*?)```/.exec(raw);
  const value = JSON.parse(fenced ? fenced[1] : raw) as Partial<Proposal>;
  if (!value || !Array.isArray(value.cases)) throw new Error('A proposal needs a "cases" array.');
  return {
    areas: value.areas ?? [],
    cases: value.cases,
    extend: value.extend ?? [],
    notE2E: value.notE2E ?? [],
    questions: value.questions ?? [],
    assumptions: value.assumptions ?? [],
  };
};

// Words two titles share, over the shorter one's words: a cheap near-duplicate test.
const overlap = (a: string, b: string): number => {
  const left = new Set(plain(a).split(" ").filter((word) => word.length > 2));
  const right = new Set(plain(b).split(" ").filter((word) => word.length > 2));
  if (!left.size || !right.size) return 0;
  let shared = 0;
  for (const word of left) if (right.has(word)) shared += 1;
  return shared / Math.min(left.size, right.size);
};
const NEAR_DUPLICATE = 0.8;

export type MergeInput = {
  proposal: Proposal;
  doneWhen: DoneWhen[];
  changedFiles: string[];
  kit: Kit | null;
  name: string;
  ticket?: string;
  app: "roam" | "obsidian";
  at: string;
};

export type MergeResult = { kit: Kit; dropped: Dropped[]; added: string[] };

// Applies the checks a model can't be trusted with, then appends what survives as proposed cases.
export const mergeProposal = (input: MergeInput): MergeResult => {
  const { proposal, doneWhen, kit } = input;
  const dropped: Dropped[] = [];
  const changed = new Set(input.changedFiles);
  const existing = kit?.cases ?? [];
  const surface: SurfaceArea[] = [...(kit?.surface ?? [])];
  const areaIds = new Map<string, string>();

  for (const area of proposal.areas) {
    const files = (area.files ?? []).filter((file) => changed.has(file));
    if (!isText(area.key) || !isText(area.area) || !isText(area.why)) {
      dropped.push({ what: `area ${area.key ?? "?"}`, reason: "needs key, area and why" });
    } else if (!files.length) {
      dropped.push({ what: `area ${area.area}`, reason: "none of its files are in the diff, so this PR doesn't reach it" });
    } else {
      const id = `s-${slug(area.key, 40)}`;
      areaIds.set(area.key, id);
      const risk = area.probability * area.impact;
      const why = `${area.why} (risk ${area.probability}×${area.impact}=${risk})`;
      const known = surface.find((item) => item.id === id);
      if (known) Object.assign(known, { area: area.area, why, files });
      else surface.push({ id, area: area.area, why, files });
    }
  }
  const riskOf = (key: string | undefined): number => {
    const area = proposal.areas.find((item) => item.key === key);
    return area ? area.probability * area.impact : 0;
  };

  const taken = new Set(existing.map((item) => item.id));
  const cases: TestCase[] = [];
  const added: string[] = [];
  for (const item of proposal.cases) {
    const label = item.title ?? "(untitled)";
    const missing = (["title", "intent", "then", "protects", "failsWhen", "whyNew"] as const).filter((key) => !isText(item[key]));
    if (missing.length) {
      dropped.push({ what: label, reason: `missing ${missing.join(", ")}` });
      continue;
    }
    if (!PRIORITIES.includes(item.priority)) {
      dropped.push({ what: label, reason: `priority must be P0–P3, not ${item.priority}` });
      continue;
    }
    let proves: string | undefined;
    if (item.kind === "acceptance") {
      const bullet = doneWhen.find((entry) => entry.number === item.doneWhen?.number);
      if (!bullet) {
        dropped.push({ what: label, reason: `Done When ${item.doneWhen?.number ?? "?"} isn't on the ticket` });
        continue;
      }
      proves = `Done When ${bullet.number}: ${bullet.text}`;
    } else if (item.kind === "regression") {
      if (!item.areaKey || !areaIds.has(item.areaKey)) {
        dropped.push({ what: label, reason: `its area ${item.areaKey ?? "(none)"} didn't survive, or isn't listed` });
        continue;
      }
      if (riskOf(item.areaKey) < MIN_RISK) {
        dropped.push({ what: label, reason: `area risk ${riskOf(item.areaKey)} is below ${MIN_RISK}` });
        continue;
      }
    } else {
      dropped.push({ what: label, reason: `kind must be acceptance or regression` });
      continue;
    }
    const twin = [...existing, ...cases].find((other) => overlap(other.title, item.title) >= NEAR_DUPLICATE);
    if (twin) {
      const was = twin.decision?.status === "rejected" ? `rejected before: ${twin.decision.reason}` : "already in the kit";
      dropped.push({ what: label, reason: `near-duplicate of ${twin.id} (${was})` });
      continue;
    }
    const base = item.kind === "regression" ? `qa-${slug(item.title, 40)}` : `dw${proves!.split(":")[0].replace(/\D/g, "")}-${slug(item.title, 40)}`;
    let id = base;
    for (let n = 2; taken.has(id); n += 1) id = `${base}-${n}`;
    taken.add(id);
    const notes = [
      `priority: ${item.priority}`,
      `protects: ${item.protects}`,
      `fails when: ${item.failsWhen}`,
      `why new: ${item.whyNew}`,
      ...(item.given ? [`given: ${item.given}`] : []),
      ...(item.variants ?? []).filter(isText).map((variant) => `variant: ${variant}`),
    ];
    const areaId = item.areaKey ? areaIds.get(item.areaKey) : undefined;
    cases.push({
      id,
      title: item.title.trim(),
      ...(proves ? { proves } : {}),
      intent: item.intent.trim(),
      checks: item.then.trim(),
      steps: [],
      notes,
      ...(areaId ? { surface: areaId } : {}),
      decision: { status: "proposed", by: "model", at: input.at },
    });
    added.push(id);
  }

  const covered = new Set([...existing, ...cases].map((item) => item.proves?.match(/^Done When (\d+)/)?.[1]).filter(Boolean));
  const excused = new Set(proposal.notE2E.map((item) => String(item.doneWhen)));
  for (const bullet of doneWhen) {
    if (!covered.has(String(bullet.number)) && !excused.has(String(bullet.number))) {
      dropped.push({ what: `Done When ${bullet.number}`, reason: "no acceptance case and no notE2E reason" });
    }
  }

  const merged = {
    ...(kit ?? { name: input.name, ...(input.ticket ? { ticket: input.ticket } : {}), target: { app: input.app, ...(input.app === "obsidian" ? { vault: "leased by the runner" } : {}) } }),
    surface,
    cases: [...existing, ...cases],
  };
  return { kit: validateKit(merged), dropped, added };
};

// A person's names only: a model or an agent proposes, it never decides.
const NOT_A_PERSON = /\b(model|claude|agent|bot|gpt|codex|assistant|ai)\b/i;

export type Decision = { id: string; status: "approved" | "rejected"; reason?: string };

export const decide = (kit: Kit, decisions: Decision[], by: string, at: string): Kit => {
  if (!isText(by) || NOT_A_PERSON.test(by)) throw new Error(`Only a person decides cases; "${by}" reads as a model or agent.`);
  const byId = new Map(kit.cases.map((item) => [item.id, item]));
  for (const decision of decisions) {
    const item = byId.get(decision.id);
    if (!item) throw new Error(`No case ${decision.id} in the kit.`);
    if (decision.status === "rejected" && !isText(decision.reason)) throw new Error(`Rejecting ${decision.id} needs a reason.`);
