  if (!isText(by) || NOT_A_PERSON.test(by)) throw new Error(`Only a person decides cases; "${by}" reads as a model or agent.`);
  const byId = new Map(kit.cases.map((item) => [item.id, item]));
  for (const decision of decisions) {
    const item = byId.get(decision.id);
    if (!item) throw new Error(`No case ${decision.id} in the kit.`);
    if (decision.status === "rejected" && !isText(decision.reason)) throw new Error(`Rejecting ${decision.id} needs a reason.`);
    item.decision = { status: decision.status, by, at, ...(decision.reason ? { reason: decision.reason } : {}) };
  }
  return validateKit(kit);
};

// What a person reads to decide: proposed cases first, grouped by Done When and area.
export const reviewMarkdown = (kit: Kit, sidecar: Pick<Proposal, "extend" | "notE2E" | "questions" | "assumptions">, dropped: Dropped[]): string => {
  const lines = [`# Proposed cases for ${kit.ticket ?? kit.name}`, ""];
  const section = (title: string, items: TestCase[]) => {
    if (!items.length) return;
    lines.push(`## ${title}`, "");
    for (const item of items) {
      lines.push(`- [ ] **${item.title}** \`${item.id}\` — ${item.decision?.status ?? "approved"}`);
      lines.push(`  - Do: ${item.intent}`, `  - Passes if: ${item.checks}`);
      for (const note of item.notes ?? []) lines.push(`  - ${note}`);
    }
    lines.push("");
  };
  const proposed = kit.cases.filter((item) => item.decision?.status === "proposed");
  section("Acceptance (Done When)", proposed.filter((item) => item.proves));
  for (const area of kit.surface ?? []) {
    section(`Regression: ${area.area}`, proposed.filter((item) => item.surface === area.id && !item.proves));
    if (proposed.some((item) => item.surface === area.id && !item.proves)) lines.splice(lines.length - 1, 0, `  _Why: ${area.why}. Files: ${(area.files ?? []).join(", ")}_`);
  }
  const listed = (title: string, items: string[]) => items.length && lines.push(`## ${title}`, "", ...items.map((item) => `- ${item}`), "");
  listed("Questions before steps are written", sidecar.questions.map((item) => `**${item.about}**: ${item.question}`));
  listed("Extend an existing case instead", sidecar.extend.map((item) => `\`${item.caseId}\`: ${item.add}`));
  listed("Not checked end to end", sidecar.notE2E.map((item) => `Done When ${item.doneWhen}: ${item.reason}`));
  listed("Assumptions (not tied to a changed line)", sidecar.assumptions);
  listed("Dropped by the checks", dropped.map((item) => `${item.what}: ${item.reason}`));
  return lines.join("\n");
};

