// propose: the model proposes kit cases, the checks drop what they can't back, a person decides.
//   cli.mjs prompt --worktree <dg> --ticket <ticket.md> [--kit k.json] [--app obsidian] [--base origin/main] --out prompt.md
//   cli.mjs merge  --worktree <dg> --ticket <ticket.md> --kit k.json --proposal answer.json [--app obsidian] [--base origin/main]
//   cli.mjs decide --kit k.json --by "Trang" [--approve <id>]... [--reject "<id>=<reason>"]...
import { execFileSync } from "node:child_process";
import { existsSync } from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import { parseArgs } from "node:util";
import { validateKit, type Kit } from "../src/core/kit";
import { decide, mergeProposal, parseDoneWhen, parseProposal, reviewMarkdown, type Decision } from "./core";

const PROMPT_FILE = path.join(import.meta.dirname, "PROMPT.md");
// A diff past this many characters per file is cut; lockfiles and fixtures say little about behaviour.
const PER_FILE_LIMIT = 6000;
const SKIP = /(^|\/)(pnpm-lock\.yaml|package-lock\.json|yarn\.lock)$|\.(png|jpg|svg|snap)$/;

const { positionals, values: args } = parseArgs({
  allowPositionals: true,
  options: {
    worktree: { type: "string" },
    ticket: { type: "string" },
    kit: { type: "string" },
    proposal: { type: "string" },
    app: { type: "string", default: "obsidian" },
    base: { type: "string", default: "origin/main" },
    out: { type: "string" },
    by: { type: "string" },
    approve: { type: "string", multiple: true, default: [] },
    reject: { type: "string", multiple: true, default: [] },
  },
});

const need = (name: string, value: string | undefined): string => {
  if (!value) throw new Error(`--${name} is required for ${positionals[0]}.`);
  return value;
};
const git = (worktree: string, ...rest: string[]): string => execFileSync("git", ["-C", worktree, ...rest], { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
const readKit = async (file: string | undefined): Promise<Kit | null> =>
  file && existsSync(file) ? validateKit(JSON.parse(await fs.readFile(file, "utf8"))) : null;
const ticketId = (ticket: string): string | undefined => /\b([A-Z]+-\d+)\b/.exec(ticket)?.[1];
const app = (): "roam" | "obsidian" => (args.app === "roam" ? "roam" : "obsidian");

const changedFiles = (worktree: string, base: string): string[] =>
  git(worktree, "diff", "--name-only", `${base}...HEAD`).split("\n").filter(Boolean);

const diffText = (worktree: string, base: string): string =>
  changedFiles(worktree, base)
    .filter((file) => !SKIP.test(file))
    .map((file) => {
      const patch = git(worktree, "diff", `${base}...HEAD`, "--", file);
      return patch.length > PER_FILE_LIMIT ? `${patch.slice(0, PER_FILE_LIMIT)}\n… (${patch.length - PER_FILE_LIMIT} more characters cut)` : patch;
    })
    .join("\n");

const kitSummary = (kit: Kit | null): string => {
  if (!kit) return "No kit yet.";
  const cases = kit.cases.map((item) => {
    const decision = item.decision ? ` [${item.decision.status}${item.decision.reason ? `: ${item.decision.reason}` : ""}]` : "";
    return `- ${item.id}: ${item.title}${decision}${item.proves ? ` (${item.proves.split(":")[0]})` : ""}`;
  });
  const areas = (kit.surface ?? []).map((area) => `- ${area.id}: ${area.area}: ${area.why}`);
  return [`Cases:`, ...cases, "", "Surface areas:", ...(areas.length ? areas : ["- none"])].join("\n");
};

const prompt = async (): Promise<void> => {
  const worktree = path.resolve(need("worktree", args.worktree));
  const ticket = await fs.readFile(need("ticket", args.ticket), "utf8");
  const doneWhen = parseDoneWhen(ticket);
  if (!doneWhen.length) throw new Error("The ticket has no Done When section with bullets.");
  const template = await fs.readFile(PROMPT_FILE, "utf8");
  const body = [
    template,
    "## Inputs",
    `### App\n${app()}`,
    `### Done When\n${doneWhen.map((item) => `${item.number}. ${item.text}`).join("\n")}`,
    `### Ticket\n${ticket}`,
    `### Existing kit\n${kitSummary(await readKit(args.kit))}`,
    `### Diff (${args.base}...HEAD)\n\`\`\`diff\n${diffText(worktree, args.base!)}\n\`\`\``,
  ].join("\n\n");
  await fs.writeFile(need("out", args.out), body);
  console.log(`prompt: ${args.out} (${body.length} characters, ${doneWhen.length} Done When bullets)`);
};

const merge = async (): Promise<void> => {
  const worktree = path.resolve(need("worktree", args.worktree));
  const kitPath = need("kit", args.kit);
  const ticket = await fs.readFile(need("ticket", args.ticket), "utf8");
  const proposal = parseProposal(await fs.readFile(need("proposal", args.proposal), "utf8"));
  const id = ticketId(ticket);
  const { kit, dropped, added } = mergeProposal({
    proposal,
    doneWhen: parseDoneWhen(ticket),
    changedFiles: changedFiles(worktree, args.base!),
    kit: await readKit(kitPath),
    name: `${(id ?? "kit").toLowerCase()}-${app()}`,
    ticket: id,
    app: app(),
    at: new Date().toISOString(),
  });
  const sidecar = { extend: proposal.extend, notE2E: proposal.notE2E, questions: proposal.questions, assumptions: proposal.assumptions, dropped };
  const stem = kitPath.replace(/\.json$/, "");
  await fs.writeFile(kitPath, `${JSON.stringify(kit, null, 2)}\n`);
  await fs.writeFile(`${stem}.proposal.json`, `${JSON.stringify(sidecar, null, 2)}\n`);
  await fs.writeFile(`${stem}.review.md`, `${reviewMarkdown(kit, sidecar, dropped)}\n`);
  console.log(`kit: ${kitPath} (+${added.length} proposed, ${dropped.length} dropped)`);
  console.log(`review: ${stem}.review.md`);
  for (const item of dropped) console.log(`  dropped ${item.what}: ${item.reason}`);
};

const decideCmd = async (): Promise<void> => {
  const kitPath = need("kit", args.kit);
  const kit = await readKit(kitPath);
  if (!kit) throw new Error(`No kit at ${kitPath}.`);
  const decisions: Decision[] = [
    ...args.approve!.map((id) => ({ id, status: "approved" as const })),
    ...args.reject!.map((entry) => {
      const at = entry.indexOf("=");
      return { id: at < 0 ? entry : entry.slice(0, at), status: "rejected" as const, reason: at < 0 ? "" : entry.slice(at + 1) };
    }),
  ];
  const next = decide(kit, decisions, need("by", args.by), new Date().toISOString());
  await fs.writeFile(kitPath, `${JSON.stringify(next, null, 2)}\n`);
  const counts = { proposed: 0, approved: 0, rejected: 0 };
  for (const item of next.cases) counts[item.decision?.status ?? "approved"] += 1;
  console.log(`kit: ${kitPath} — ${counts.approved} approved, ${counts.rejected} rejected, ${counts.proposed} still proposed`);
};

const commands: Record<string, () => Promise<void>> = { prompt, merge, decide: decideCmd };
const run = commands[positionals[0] ?? ""];
if (!run) {
  console.error("usage: cli.mjs prompt | merge | decide (see the header of propose/cli.ts)");
  process.exit(1);
}
run().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
});

