    expect(parseDoneWhen(TICKET)).toEqual([
      { number: 1, text: "A text shape exposes the same **Edit link** action as a geo shape." },
      { number: 2, text: "A user can add, edit, open, and remove a link on a text shape.; with the same affordance as a geo shape" },
      { number: 3, text: "Unit tests cover link persistence." },
    ]);
  });
});

describe("parseProposal", () => {
  it("reads JSON inside a fence and defaults the optional lists", () => {
    const parsed = parseProposal('Here:\n```json\n{"cases": []}\n```');
    expect(parsed).toMatchObject({ cases: [], areas: [], questions: [] });
  });
});

describe("mergeProposal", () => {
  it("adds proposed acceptance cases that prove the ticket's own Done When text", () => {
    const { kit, added } = merge(
      proposal({ cases: [baseCase({}), baseCase({ doneWhen: { number: 2, text: "x" }, title: "Remove a link from a text shape" })] }),
    );
    expect(added).toEqual(["dw1-a-text-shape-offers-edit-link", "dw2-remove-a-link-from-a-text-shape"]);
    expect(kit.cases[0]).toMatchObject({
      proves: "Done When 1: A text shape exposes the same **Edit link** action as a geo shape.",
      decision: { status: "proposed", by: "model" },
      checks: "Edit link is listed.",
    });
    expect(kit.cases[0].notes).toContain("priority: P1");
  });

  it("drops areas whose files aren't in the diff, and the cases that hang off them", () => {
    const { dropped, kit } = merge(
      proposal({
        areas: [{ key: "search", area: "Node search", why: "w", files: ["apps/obsidian/src/search.ts"], probability: 3, impact: 3 }],
        cases: [baseCase({}), baseCase({ kind: "regression", doneWhen: undefined, areaKey: "search", title: "Search still finds nodes" })],
      }),
    );
    expect(kit.surface).toEqual([]);
    expect(dropped.map((item) => item.reason)).toEqual([
      "none of its files are in the diff, so this PR doesn't reach it",
      "its area search didn't survive, or isn't listed",
      "no acceptance case and no notE2E reason",
    ]);
  });

  it("keeps regression cases only for areas with probability × impact of 3 or more", () => {
    const area = (key: string, probability: number) => ({ key, area: key, why: "w", files: ["patches/tldraw.patch"], probability, impact: 1 });
    const { added, dropped } = merge(
      proposal({
        areas: [area("geo", 3), area("toast", 2)],
        cases: [
          baseCase({}),
          baseCase({ doneWhen: { number: 2, text: "" }, title: "Edit a text link" }),
          baseCase({ kind: "regression", doneWhen: undefined, areaKey: "geo", title: "Geo shapes still take links" }),
          baseCase({ kind: "regression", doneWhen: undefined, areaKey: "toast", title: "Toast colour unchanged" }),
        ],
      }),
    );
    expect(added).toContain("qa-geo-shapes-still-take-links");
    expect(dropped).toContainEqual({ what: "Toast colour unchanged", reason: "area risk 2 is below 3" });
  });

  it("drops a near-duplicate of a rejected case and says why it was rejected", () => {
    const first = merge(proposal({ cases: [baseCase({}), baseCase({ doneWhen: { number: 2, text: "" }, title: "Edit a text link" })] })).kit;
    first.cases[1].decision = { status: "rejected", by: "Trang", reason: "another case covers it" };
    const { dropped } = merge(proposal({ cases: [baseCase({ doneWhen: { number: 2, text: "" }, title: "Edit a link on a text shape" })] }), first as never);
    expect(dropped[0].reason).toBe("near-duplicate of dw2-edit-a-text-link (rejected before: another case covers it)");
  });

  it("refuses a Done When number the ticket doesn't have", () => {
    const { dropped } = merge(proposal({ cases: [baseCase({ doneWhen: { number: 9, text: "" } })] }));
    expect(dropped[0]).toEqual({ what: "A text shape offers Edit link", reason: "Done When 9 isn't on the ticket" });
  });
});

describe("decide", () => {
  const kit = () => merge(proposal({ cases: [baseCase({}), baseCase({ doneWhen: { number: 2, text: "" }, title: "Edit a text link" })] })).kit;

  it("records a person's approval and rejection with its reason", () => {
    const next = decide(kit(), [
      { id: "dw1-a-text-shape-offers-edit-link", status: "approved" },
      { id: "dw2-edit-a-text-link", status: "rejected", reason: "covered" },
    ], "Trang", "now");
    expect(next.cases.map((item) => item.decision)).toEqual([
      { status: "approved", by: "Trang", at: "now" },
      { status: "rejected", by: "Trang", at: "now", reason: "covered" },
    ]);
  });

  it("refuses decisions by a model or agent, and rejections without a reason", () => {
    expect(() => decide(kit(), [{ id: "dw1-a-text-shape-offers-edit-link", status: "approved" }], "Claude, for sid", "now")).toThrow(/Only a person/);
    expect(() => decide(kit(), [{ id: "dw2-edit-a-text-link", status: "rejected" }], "Trang", "now")).toThrow(/needs a reason/);
  });
});

