content.content:
1	// The Executor for a run against Obsidian over CDP: Roam's page executor's
2	// actions and Playwright-style waits, with trusted input, real screenshots,
3	// and commands run by id instead of typed into the palette.
4	import fs from "node:fs/promises";
5	import path from "node:path";
6	import type { Action } from "../src/core/action";
7	import type { ActionHooks, Executor, MachineState } from "../src/core/machine";
8	import { evaluateIn, type CdpSession, type Returns } from "./cdp";
9	import { comboEvents } from "./keys";
10	import { pickCommand, type PaletteCommand } from "./palette";
11	
12	export type CdpExecutorOptions = {
13	  session: CdpSession;
14	  timeout: number;
15	  // Fills {{run}}, {{kit}}, {{ns}} and {{env.X}} in every string of an action.
16	  fill: <T>(value: T) => T;
17	  render: (state: MachineState) => Promise<void>;
18	  // Something a person should know that isn't a failure.
19	  note: (text: string) => void;
20	  // How long the ring shows before the step acts.
21	  lead: () => number;
22	  screenshotDir: string;
23	};
24	
25	const sleep = (ms: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, ms));
26	const json = JSON.stringify;
27	
28	const HELD = new Error("held");
29	const STOPPED = new Error("stopped");
30	const POLL_MS = 100;
31	const BUTTONS = { left: 1, middle: 4, right: 2 } as const;
32	
33	type Probe = { ok: true; x: number; y: number } | { ok: false; reason: string };
34	
35	export const makeCdpExecutor = (options: CdpExecutorOptions): Executor & { screenshots: string[] } => {
36	  const { session, timeout } = options;
37	  const screenshots: string[] = [];
38	  const page = (js: string, returns: Returns = "value"): Promise<unknown> => evaluateIn(session, js, returns);
39	  const hud = (call: string): Promise<unknown> => page(`window.__proofHud && window.__proofHud.${call}`);
40	
41	  const waitUntil = async <T>(probe: () => Promise<T | null | false>, what: () => string): Promise<T> => {
42	    const deadline = Date.now() + timeout;
43	    for (;;) {
44	      const value = await probe();
45	      if (value) return value;
46	      if (Date.now() > deadline) throw new Error(`Timeout ${timeout}ms exceeded waiting for ${what()}.`);
47	      await sleep(POLL_MS);
48	    }
49	  };
50	
51	  const visible = (selector: string): Promise<true> =>
52	    waitUntil(async () => (await hud(`visible(${json(selector)})`)) === true || null, () => selector);
53	
54	  // Visible, enabled, still and uncovered, as Playwright waits before a click.
55	  const actionable = async (selector: string, position?: { x: number; y: number }): Promise<{ x: number; y: number }> => {
56	    let last = "";
57	    let before: { x: number; y: number } | null = null;
58	    return waitUntil(
59	      async () => {
60	        const probe = (await hud(`actionable(${json(selector)}${position ? `, ${json(position)}` : ""})`)) as Probe | undefined;
61	        if (!probe) throw new Error("The runner's page half is gone; the page reloaded.");
62	        if (!probe.ok) {
63	          last = probe.reason;
64	          before = null;
65	          return null;
66	        }
67	        const still: boolean = before !== null && before.x === probe.x && before.y === probe.y;
68	        before = { x: probe.x, y: probe.y };
69	        if (!still) last = "the element is still moving";
70	        return still ? { x: probe.x, y: probe.y } : null;
71	      },
72	      () => `${selector}: ${last || "not found"}`,
73	    );
74	  };
75	
76	  // Our input is trusted, so the stage lets it through only while we act.
77	  const acting = async <T>(work: () => Promise<T>): Promise<T> => {
78	    await hud("passing(true)");
79	    try {
80	      return await work();
81	    } finally {
82	      await hud("passing(false)").catch(() => undefined);
83	    }
84	  };
85	
86	  const mouse = (type: string, x: number, y: number, extra: Record<string, unknown> = {}) =>
87	    session.send("Input.dispatchMouseEvent", { type, x, y, pointerType: "mouse", ...extra });
88	
89	  const clickAt = (point: { x: number; y: number }, button: keyof typeof BUTTONS = "left", count = 1) =>
90	    acting(async () => {
91	      await mouse("mouseMoved", point.x, point.y);
92	      for (let n = 1; n <= count; n += 1) {
93	        await mouse("mousePressed", point.x, point.y, { button, buttons: BUTTONS[button], clickCount: n });
94	        await mouse("mouseReleased", point.x, point.y, { button, buttons: 0, clickCount: n });
95	      }
96	    });
97	
98	  const press = (combo: string) =>
99	    acting(async () => {
100	      for (const event of comboEvents(combo)) await session.send("Input.dispatchKeyEvent", event);
101	    });
102	
103	  const typeText = async (text: string, delayMs: number, hooks?: ActionHooks) => {
104	    for (const char of text) {
105	      const outcome = (await hooks?.hold()) ?? "go";
106	      if (outcome === "interrupted") throw STOPPED;
107	      await acting(async () => {
108	        if (char === "\n") await pressRaw("Enter");
109	        else await session.send("Input.insertText", { text: char });
110	      });
111	      if (delayMs > 0) await sleep(delayMs);
112	    }
113	  };
114	  const pressRaw = async (combo: string) => {
115	    for (const event of comboEvents(combo)) await session.send("Input.dispatchKeyEvent", event);
116	  };
117	
118	  const show = async (selector: string | null, verb: string): Promise<void> => {
119	    await hud(`target(${json(selector)}, ${json(verb)}, ${options.lead()})`);
120	    if (selector) await sleep(options.lead());
121	  };
122	
123	  const gate = async (hooks: ActionHooks | undefined): Promise<void> => {
124	    const outcome = (await hooks?.hold()) ?? "go";
125	    if (outcome === "held") throw HELD;
126	    if (outcome === "interrupted") throw STOPPED;
127	  };
128	
129	  // Commands by id: the palette's own UI is a modal a run would have to clean up.
130	  const runCommand = async (label: string): Promise<void> => {
131	    const commands = (await page(
132	      "Object.values(app.commands.commands).map((command) => ({ id: command.id, name: command.name }))",
133	    )) as PaletteCommand[];
134	    const { command, candidates } = pickCommand(label, commands);
135	    if (!command) {
136	      const names = candidates.slice(0, 5).map((item) => item.name).join("; ");
137	      throw new Error(
138	        candidates.length
