  press(combo: string): Promise<void>;
  // A kit's js or check: indirect eval in the page, a promise awaited.
  run(js: string, returns: Returns): Promise<unknown>;
  screenshot(): Promise<Buffer>;
};

const BUTTONS: Record<Button, number> = { left: 1, middle: 4, right: 2 };

export const cdpInput = (session: CdpSession): PageInput => {
  const mouse = (type: string, x: number, y: number, extra: Record<string, unknown> = {}) =>
    session.send("Input.dispatchMouseEvent", { type, x, y, pointerType: "mouse", ...extra }).then(() => undefined);
  const press = async (combo: string) => {
    for (const event of comboEvents(combo)) await session.send("Input.dispatchKeyEvent", event);
  };
  return {
    move: (x, y) => mouse("mouseMoved", x, y),
    click: async (x, y, button, count) => {
      await mouse("mouseMoved", x, y);
      for (let n = 1; n <= count; n += 1) {
        await mouse("mousePressed", x, y, { button, buttons: BUTTONS[button], clickCount: n });
        await mouse("mouseReleased", x, y, { button, buttons: 0, clickCount: n });
      }
    },
    down: (x, y) => mouse("mousePressed", x, y, { button: "left", buttons: 1, clickCount: 1 }),
    up: (x, y) => mouse("mouseReleased", x, y, { button: "left", buttons: 0, clickCount: 1 }),
    wheel: (deltaY) => mouse("mouseWheel", 640, 360, { deltaX: 0, deltaY }),
    insertText: (text) => session.send("Input.insertText", { text }).then(() => undefined),
    press,
    run: (js, returns) => evaluateIn(session, js, returns),
    screenshot: async () => Buffer.from(((await session.send("Page.captureScreenshot", { format: "png" })) as { data: string }).data, "base64"),
  };
};

// The slice of a Playwright Page the traced input uses; typed here so the runner doesn't
// need Playwright's types at build time.
export type PlaywrightPage = {
  mouse: {
    move(x: number, y: number): Promise<void>;
    click(x: number, y: number, options: { button: Button; clickCount: number }): Promise<void>;
    down(): Promise<void>;
    up(): Promise<void>;
    wheel(deltaX: number, deltaY: number): Promise<void>;
  };
  keyboard: { insertText(text: string): Promise<void>; press(key: string): Promise<void> };
  evaluate<R, A>(fn: (arg: A) => R | Promise<R>, arg: A): Promise<R>;
  screenshot(): Promise<Buffer>;
};

export const playwrightInput = (page: PlaywrightPage): PageInput => ({
  move: (x, y) => page.mouse.move(x, y),
  click: (x, y, button, count) => page.mouse.click(x, y, { button, clickCount: count }),
  down: async (x, y) => {
    await page.mouse.move(x, y);
    await page.mouse.down();
  },
  up: async (x, y) => {
    await page.mouse.move(x, y);
    await page.mouse.up();
  },
  wheel: (deltaY) => page.mouse.wheel(0, deltaY),
  insertText: (text) => page.keyboard.insertText(text),
  press: (combo) => page.keyboard.press(combo),
  run: (js, returns) =>
    page.evaluate(
      ([source, shape]) =>
        Promise.resolve((0, eval)(source)).then((value: unknown) => (shape === "value" ? value : shape === "truthy" ? Boolean(value) : undefined)),
      [js, returns] as const,
    ),
  screenshot: () => page.screenshot(),
});

