input.content:
// A Playwright trace of a run, for the trace viewer: each case is a group, each step a
// group inside it, and every click, key and js step an action with DOM snapshots.
import type { MachineState } from "../src/core/machine";
import { playwrightInput, type PageInput, type PlaywrightPage } from "./input";

type Tracing = {
  start(options: { screenshots: boolean; snapshots: boolean; title: string }): Promise<void>;
  stop(options: { path: string }): Promise<void>;
  group(name: string): Promise<void>;
  groupEnd(): Promise<void>;
};
type Page = PlaywrightPage & { evaluate<R>(fn: () => R | Promise<R>): Promise<R> };
type Context = { pages(): Page[]; tracing: Tracing };
type Browser = { contexts(): Context[] };

export type Trace = {
  input: PageInput;
  // Follows the machine: opens and closes the case and step groups as it moves.
  follow(state: MachineState): Promise<void>;
  stop(path: string): Promise<void>;
};

// Obsidian's stylesheets load from app://, which snapshots can't fetch: copy their rules
// into inline <style> while tracing, and undo it after.
const inlineStyles = () => {
  for (const sheet of Array.from(document.styleSheets)) {
    const owner = sheet.ownerNode;
    if (!(owner instanceof HTMLLinkElement) || owner.disabled) continue;
    let rules = "";
    try {
      rules = Array.from(sheet.cssRules).map((rule) => rule.cssText).join("\n");
    } catch {
      continue;
    }
    const style = document.createElement("style");
    style.dataset.proofInlined = "";
    style.textContent = rules;
    owner.after(style);
    owner.dataset.proofDisabled = "";
    owner.disabled = true;
  }
};
const restoreStyles = () => {
