// The catalog's data: a manifest of kits, their cases and their runs, merged one run at a
// time. Pure, so the merge and the safety scan are tested without Blob or a run on disk.

export const BASE = "releases/proof";
// The manifest keeps this many runs per kit; older run files stay until a cleanup deletes them.
export const RUNS_KEPT = 20;

export type Verdict = "pass" | "fail" | "skip" | "left-out" | "not-run";

export type RunFile = {
  kit: string;
  app: string;
  startedAt: string;
  endedAt: string;
  build: string;
  branch: string;
  commit: string;
  how: string;
  verdicts: Record<string, Verdict>;
  notRun: Array<{ id: string; status: string; reason: string | null }>;
};

type KitCase = {
  id: string;
  title: string;
  proves?: string;
  checks?: string;
  intent?: string;
  surface?: string;
  decision?: { status: string; by?: string; reason?: string };
  steps?: Array<{ why: string }>;
};
export type KitFile = {
  name: string;
  title?: string;
  ticket?: string;
  claim?: string;
  target?: { app?: string; pr?: number };
  surface?: Array<{ id: string; area: string; why: string }>;
  cases: KitCase[];
};

export type ManifestRun = {
  id: string;
  startedAt: string;
  build: string;
  branch: string;
  commit: string;
  how: string;
  verdicts: Record<string, Verdict>;
  passed: number;
  total: number;
  files: { trace?: string; result: string; records: string };
};
export type ManifestKit = {
  name: string;
  title: string;
  ticket: string | null;
  app: string;
  pr: number | null;
  claim: string | null;
  surface: Array<{ id: string; area: string; why: string }>;
  cases: Array<Omit<KitCase, "steps"> & { steps: string[] }>;
  runs: ManifestRun[];
};
export type Manifest = { version: 1; updatedAt: string; kits: Record<string, ManifestKit> };

export const emptyManifest = (): Manifest => ({ version: 1, updatedAt: new Date(0).toISOString(), kits: {} });

// Sortable and unique per run: when it started, and the build it ran.
export const runId = (run: RunFile): string => `${run.startedAt.replace(/[:.]/g, "-").slice(0, 19)}-${run.commit.slice(0, 7)}`;

export const runPaths = (kit: string, id: string) => {
  const dir = `${BASE}/runs/${kit}/${id}`;
  return { dir, trace: `${dir}/trace.zip`, result: `${dir}/result.md`, records: `${dir}/records.json`, kit: `${dir}/kit.json` };
};

// Adds a run, and refreshes the kit's cases from the kit that run used.
