// Short-lived: they change on every publish. Run files never change, so they keep the default.
const FRESH_SECONDS = 60;
// A JWT in any text the trace keeps: a token that slipped past the header scrub.
const JWT = /eyJ[\w-]{8,}\.eyJ[\w-]{8,}\.[\w-]{8,}/;

const { values: args } = parseArgs({
  options: {
    run: { type: "string" },
    local: { type: "string" },
    "no-trace": { type: "boolean", default: false },
  },
});

const TYPES: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json",
  ".md": "text/markdown; charset=utf-8",
  ".zip": "application/zip",
  ".svg": "image/svg+xml",
  ".ttf": "font/ttf",
  ".webmanifest": "application/manifest+json",
  ".txt": "text/plain; charset=utf-8",
};
const typeOf = (file: string): string => TYPES[path.extname(file)] ?? "application/octet-stream";

type Store = {
  where: string;
  read(pathname: string): Promise<string | null>;
  write(pathname: string, body: Buffer | string, fresh?: boolean): Promise<void>;
};

const localStore = (root: string): Store => ({
  where: root,
  read: async (pathname) => (existsSync(path.join(root, pathname)) ? fs.readFile(path.join(root, pathname), "utf8") : null),
  write: async (pathname, body) => {
    await fs.mkdir(path.dirname(path.join(root, pathname)), { recursive: true });
    await fs.writeFile(path.join(root, pathname), body);
  },
});

const blobStore = async (): Promise<Store> => {
  if (!process.env.BLOB_READ_WRITE_TOKEN) throw new Error("BLOB_READ_WRITE_TOKEN is required to publish to Vercel Blob (or pass --local <dir>).");
  const { put, head } = (await import("@vercel/blob")) as typeof import("@vercel/blob");
  return {
    where: "Vercel Blob (public)",
    read: async (pathname) => {
      const found = await head(pathname).catch(() => null);
      if (!found) return null;
      const response = await fetch(`${found.url}?fresh=${Date.now()}`, { cache: "no-store" });
      return response.ok ? response.text() : null;
    },
    write: async (pathname, body, fresh = false) => {
      await put(pathname, body, {
        access: "public",
        addRandomSuffix: false,
        allowOverwrite: true,
        contentType: typeOf(pathname),
        ...(fresh ? { cacheControlMaxAge: FRESH_SECONDS } : {}),
      });
    },
  };
};

// Strips credentials from the trace, refuses if any text still holds a token, and zips it again.
const safeTrace = async (trace: string): Promise<Buffer> => {
  const work = await fs.mkdtemp(path.join(os.tmpdir(), "proof-trace-"));
  try {
    execFileSync("unzip", ["-q", trace, "-d", work]);
    const network = path.join(work, "trace.network");
    if (existsSync(network)) {
      const { kept, removed, resources } = scrubNetwork((await fs.readFile(network, "utf8")).split("\n"));
      await fs.writeFile(network, `${kept.join("\n")}\n`);
      for (const sha of new Set(resources)) await fs.rm(path.join(work, "resources", sha), { force: true });
      const left = scanNetwork(kept);
      if (left.length) throw new Error(`The trace still has credential headers: ${left.map((item) => `${item.header} on ${item.url}`).join("; ")}`);
      if (removed.length) console.log(`trace: removed ${new Set(removed.map((item) => item.url)).size} requests carrying ${[...new Set(removed.map((item) => item.header))].join(", ")}`);
    }
    for (const file of await fs.readdir(work, { recursive: true })) {
      const full = path.join(work, file);
      if ((await fs.stat(full)).isDirectory()) continue;
      if (JWT.test(await fs.readFile(full, "latin1"))) throw new Error(`${file} in the trace holds something shaped like a token; not publishing it.`);
    }
    const zipped = path.join(work, "..", `${path.basename(work)}.zip`);
    execFileSync("zip", ["-qr", "-X", zipped, "."], { cwd: work });
    const body = await fs.readFile(zipped);
    await fs.rm(zipped, { force: true });
    return body;
  } finally {
    await fs.rm(work, { recursive: true, force: true });
  }
};

// The viewer is uploaded once per Playwright version, next to the traces, so links need no CORS.
const publishViewer = async (store: Store): Promise<void> => {
  const require = createRequire(import.meta.url);
  const core = path.dirname(require.resolve("playwright-core/package.json"));
  const version = JSON.parse(await fs.readFile(path.join(core, "package.json"), "utf8")).version as string;
  if ((await store.read(`${BASE}/viewer/version.txt`))?.trim() === version) return;
  const dir = path.join(core, "lib", "vite", "traceViewer");
  for (const file of await fs.readdir(dir, { recursive: true })) {
    const full = path.join(dir, file);
    if ((await fs.stat(full)).isFile()) await store.write(`${BASE}/viewer/${file.split(path.sep).join("/")}`, await fs.readFile(full));
  }
  await store.write(`${BASE}/viewer/version.txt`, version, true);
  console.log(`viewer: Playwright ${version} trace viewer published`);
};

const main = async (): Promise<void> => {
  if (!args.run) throw new Error("usage: cli.mjs --run <runner out dir> [--local <dir>] [--no-trace]");
  const runDir = path.resolve(args.run);
  const read = (file: string) => fs.readFile(path.join(runDir, file), "utf8");
  const run = JSON.parse(await read("run.json")) as RunFile;
  const kit = JSON.parse(await read("kit.json")) as KitFile;
  const id = runId(run);
  const paths = runPaths(kit.name, id);
  const hasTrace = !args["no-trace"] && existsSync(path.join(runDir, "trace.zip"));
  // Scrub before anything is written, so a refusal leaves the store untouched.
  const trace = hasTrace ? await safeTrace(path.join(runDir, "trace.zip")) : null;

  const store = args.local ? localStore(path.resolve(args.local)) : await blobStore();
  if (trace) await store.write(paths.trace, trace);
  await store.write(paths.result, await read("result.md"));
  await store.write(paths.records, await read("records.json"));
  await store.write(paths.kit, await read("kit.json"));

  const relative = (pathname: string) => pathname.slice(BASE.length + 1);
  const current = await store.read(`${BASE}/manifest.json`);
  const manifest = mergeRun(current ? (JSON.parse(current) as Manifest) : emptyManifest(), kit, run, {
    ...(trace ? { trace: relative(paths.trace) } : {}),
    result: relative(paths.result),
    records: relative(paths.records),
  }, new Date().toISOString());
  await store.write(`${BASE}/manifest.json`, `${JSON.stringify(manifest, null, 2)}\n`, true);
  await store.write(`${BASE}/index.html`, await fs.readFile(SITE), true);
  await publishViewer(store);

  const ran = manifest.kits[kit.name].runs[0];
  console.log(`published ${kit.name} run ${id} (${ran.passed}/${ran.total} passed) to ${store.where}`);
  console.log(`catalog: ${args.local ? path.join(store.where, BASE, "index.html") : "https://discoursegraphs.com/releases/proof/"}`);
};

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
});

