// A run's walkthrough for the catalog page: each case's steps and actions with the screen
// before and after them, cut from the trace's screencast so the page needs no trace viewer.
export type TraceEvent = {
  type: string;
  callId?: string;
  parentId?: string;
  title?: string;
  method?: string;
  params?: Record<string, unknown>;
  startTime?: number;
  endTime?: number;
  error?: { message?: string };
  timestamp?: number;
  sha1?: string;
  width?: number;
  height?: number;
};

export type WalkAction = { label: string; detail: string | null; ms: number; error: string | null; before: string | null; after: string | null; point: { x: number; y: number } | null };
export type WalkStep = { title: string; kind: "step" | "check"; ms: number; error: string | null; before: string | null; after: string | null; actions: WalkAction[] };
export type WalkCase = { index: number; title: string; steps: WalkStep[] };
export type Walkthrough = { width: number; height: number; cases: WalkCase[] };

const CASE_GROUP = /^Case (\d+)\/\d+: (.*)$/;
// The kit's js, out of the expression the runner wraps it in.
const kitJs = (expression: string): string => {
  const match = /^Promise\.resolve\(\(0, eval\)\(("(?:[^"\\]|\\.)*")\)\)/.exec(expression);
  if (!match) return expression;
  try {
    return JSON.parse(match[1]) as string;
  } catch {
    return expression;
  }
};
const describe = (method: string, params: Record<string, unknown>): { label: string; detail: string | null } => {
  switch (method) {
    case "mouseClick":
      return { label: params.button === "right" ? "Right-click" : Number(params.clickCount) > 1 ? "Double-click" : "Click", detail: null };
    case "keyboardPress":
      return { label: `Press ${String(params.key)}`, detail: null };
    case "keyboardInsertText":
      return { label: "Type", detail: String(params.text ?? "") };
    case "evaluateExpression":
      return { label: "Run js", detail: kitJs(String(params.expression ?? "")) };
    case "mouseMove":
      return { label: "Move the mouse", detail: null };
    case "mouseDown":
      return { label: "Press the mouse", detail: null };
    case "mouseUp":
      return { label: "Release the mouse", detail: null };
    case "mouseWheel":
      return { label: "Scroll", detail: null };
    case "screenshot":
      return { label: "Screenshot", detail: null };
    default:
      return { label: method, detail: null };
  }
};

export const walkthrough = (events: TraceEvent[]): Walkthrough => {
  const frames = events.filter((event) => event.type === "screencast-frame" && event.sha1 && event.timestamp !== undefined).sort((a, b) => a.timestamp! - b.timestamp!);
  const ends = new Map(events.filter((event) => event.type === "after").map((event) => [event.callId!, event]));
  const calls = events.filter((event) => event.type === "before" && event.callId).sort((a, b) => a.startTime! - b.startTime!);
  const children = (id: string | undefined) => calls.filter((call) => call.parentId === id);
  // The last frame at or before a moment.
  const frameAt = (time: number): string | null => {
    let found: string | null = null;
    for (const frame of frames) {
      if (frame.timestamp! > time) break;
      found = frame.sha1!;
    }
    return found;
  };
  const leaves = calls.filter((call) => call.method && call.method !== "tracingGroup" && !children(call.callId).length);
  const nextStart = (time: number): number => leaves.find((call) => call.startTime! > time)?.startTime ?? Infinity;
  const endOf = (call: TraceEvent): number => ends.get(call.callId!)?.endTime ?? call.startTime!;
  const settled = (end: number): string | null => frameAt(Math.min(nextStart(end) - 1, end + 1500));
  const errorOf = (call: TraceEvent): string | null => ends.get(call.callId!)?.error?.message?.split("\n")[0] ?? null;

  const actionsUnder = (group: TraceEvent): WalkAction[] =>
    children(group.callId).flatMap((call) => {
      if (children(call.callId).length) return actionsUnder(call);
      const { label, detail } = describe(call.method ?? "", call.params ?? {});
      const point = call.method === "mouseClick" && typeof call.params?.x === "number" ? { x: call.params.x as number, y: call.params.y as number } : null;
      return [{ label, detail, ms: Math.round(endOf(call) - call.startTime!), error: errorOf(call), before: frameAt(call.startTime!), after: settled(endOf(call)), point }];
    });

  const cases: WalkCase[] = [];
  for (const group of calls.filter((call) => !call.parentId && CASE_GROUP.test(call.title ?? ""))) {
    const [, index, title] = CASE_GROUP.exec(group.title!)!;
    const steps = children(group.callId)
      .filter((step) => /^(Step \d+|Check): /.test(step.title ?? ""))
      .map((step): WalkStep => {
        const actions = actionsUnder(step);
        return {
          title: step.title!.replace(/^Step \d+: /, ""),
          kind: step.title!.startsWith("Check: ") ? "check" : "step",
          ms: Math.round(endOf(step) - step.startTime!),
          error: actions.find((action) => action.error)?.error ?? null,
          before: frameAt(step.startTime!),
          after: settled(endOf(step)),
          actions,
        };
      });
    cases.push({ index: Number(index), title, steps });
  }
  const first = frames[0];
  return { width: first?.width ?? 0, height: first?.height ?? 0, cases };
};

// Every frame a walkthrough points at, so publish uploads only those.
export const walkFrames = (walk: Walkthrough): string[] =>
  [...new Set(walk.cases.flatMap((item) => item.steps.flatMap((step) => [step.before, step.after, ...step.actions.flatMap((action) => [action.before, action.after])])))].filter(
    (sha): sha is string => Boolean(sha),
  );
EOF
