import os, re, subprocess
from collections import defaultdict, deque
ROOTS = {"~/": "apps/obsidian/src/", "@repo/database/": "packages/database/src/", "@repo/utils/": "packages/utils/src/"}
EXTS = [".ts", ".tsx", "/index.ts", "/index.tsx", ""]
files = subprocess.run(["git","ls-tree","-r","--name-only","origin/main","--","apps/obsidian/src","packages/database/src","packages/utils/src"],capture_output=True,text=True).stdout.split()
src = {f for f in files if f.endswith((".ts",".tsx")) and "__tests__" not in f and ".test." not in f}
imp = re.compile(r"""(?:import|export)[^'"]*?from\s*['"]([^'"]+)['"]|import\(\s*['"]([^'"]+)['"]\s*\)""")
def resolve(frm, spec):
    base = None
    for k,v in ROOTS.items():
        if spec.startswith(k): base = v + spec[len(k):]
    if spec.startswith("."): base = os.path.normpath(os.path.join(os.path.dirname(frm), spec))
    if base is None: return None
    for e in EXTS:
        if base + e in src: return base + e
    return None
importers = defaultdict(set)
for f in src:
    text = subprocess.run(["git","show",f"origin/main:{f}"],capture_output=True,text=True).stdout
    for m in imp.finditer(text):
        t = resolve(f, m.group(1) or m.group(2))
        if t: importers[t].add(f)
# Features = UI entry points (where a user meets it), not folders.
features = {
  "canvas: relations & links": ["apps/obsidian/src/components/canvas/TldrawViewComponent.tsx"],
  "node creation & context view": ["apps/obsidian/src/components/DiscourseContextView.tsx", "apps/obsidian/src/utils/createNode.ts"],
  "advanced node search": [f for f in src if re.search(r"components/.*Search.*\.tsx$", f)],
  "import shared nodes": [f for f in src if re.search(r"components/.*Import.*\.tsx$", f)],
  "settings": [f for f in src if re.search(r"components/settings/.*\.tsx$", f)],
}
def reaches(changed):
    seen, q = set(changed), deque(changed)
    while q:
        for up in importers[q.popleft()]:
            if up not in seen: seen.add(up); q.append(up)
    return {name for name, entries in features.items() if seen & set(entries)}
for sha_subj in subprocess.run(["git","log","origin/main","--first-parent","-n","25","--format=%h\t%s","--","apps/obsidian"],capture_output=True,text=True).stdout.strip().split("\n"):
    sha, subj = sha_subj.split("\t",1)
    if not re.match(r"ENG-(2176|2339|2372|2195|2256|2228|2266|2336|2323)\b", subj): continue
    changed = [f for f in subprocess.run(["git","diff-tree","--no-commit-id","--name-only","-r",sha],capture_output=True,text=True).stdout.split() if f in src]
    print(f"{subj[:60]:60} -> {sorted(reaches(changed)) or '—'}")
print(f"\n(graph: {len(src)} files, {sum(len(v) for v in importers.values())} import edges)")
EOF

